import React, { useState, useEffect } from "react";
import { 
  ArrowLeft, Mail, Phone, Send, X, ExternalLink, Save, Edit2, Calendar, CheckCircle, XCircle 
} from "lucide-react";
import axios from "axios";
import { syncToGoogleSheets } from "../utils/googleSheets"; // make sure this path is correct

const GAMYAM_COLORS = {
  darkBg: '#0f0f10',
  darkCard: '#2c2c2d',
  darkGray: '#4a4a4b',
  orange: '#ff7c26',
  textLight: '#ffffff',
  textMuted: '#b2b2b3',
  textDim: '#8e8e8e',
  border: '#4a4a4b',
};

const GOOGLE_SHEET_ID = '1wgNsZ5mtOCaj6vnvD84ECMnx-Hw3cFzmlUxwiQTUQzo';

function RecruiterActionsPage({ applicant, onBack }) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [sending, setSending] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [isRejected, setIsRejected] = useState(false);

  // Form states
  const [roundStatus, setRoundStatus] = useState("Round 1");
  const [feedback, setFeedback] = useState("");
  const [allFeedback, setAllFeedback] = useState("");
  const [scheduledDate, setScheduledDate] = useState("");
  const [scheduledTime, setScheduledTime] = useState("");
  const [interviewerName, setInterviewerName] = useState("");
  const [interviewerEmail, setInterviewerEmail] = useState("");
  const [interviewerPhone, setInterviewerPhone] = useState("");
  const [panelNumber, setPanelNumber] = useState("");
  const [scheduledBy, setScheduledBy] = useState("");
  const [interviewPlace, setInterviewPlace] = useState("");

  // Modal states
  const [showEmailModal, setShowEmailModal] = useState(false);
  const [showInviteModal, setShowInviteModal] = useState(false);
  const [showPromoteModal, setShowPromoteModal] = useState(false);
  const [emailData, setEmailData] = useState({ subject: "", body: "" });

  useEffect(() => {
    loadRecruiterActions();
  }, [applicant._id]);

  /** Load existing recruiter actions from backend */
  const loadRecruiterActions = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`http://localhost:5000/api/recruiter-actions/${applicant._id}`);
      const data = response.data;

      setRoundStatus(data.roundStatus || "Round 1");
      setAllFeedback(data.feedback || "");
      setScheduledDate(data.scheduledDate || "");
      setScheduledTime(data.scheduledTime || "");
      setInterviewerName(data.interviewerName || "");
      setInterviewerEmail(data.interviewerEmail || "");
      setInterviewerPhone(data.interviewerPhone || "");
      setPanelNumber(data.panelNumber || "");
      setScheduledBy(data.scheduledBy || "");
      setInterviewPlace(data.interviewPlace || "");
      setIsRejected(data.isRejected || false);

      // Extract feedback for current round
      const feedbackLines = (data.feedback || "").split('\n');
      const currentRoundFeedback = feedbackLines.find(line => line.startsWith(`${data.roundStatus}:`));
      setFeedback(currentRoundFeedback ? currentRoundFeedback.replace(`${data.roundStatus}:`, '').trim() : "");

      setIsEditing(!(data.scheduledDate || data.interviewerName));
      console.log('✅ Loaded existing recruiter actions');
    } catch (err) {
      console.error('Error loading recruiter actions:', err);
    } finally {
      setLoading(false);
    }
  };

  /** Save schedule details & sync to Google Sheets */
  const handleSaveScheduleDetails = async () => {
    if (!scheduledDate || !scheduledTime || !interviewerName || !interviewerEmail || !scheduledBy || !interviewPlace || !panelNumber) {
      alert("Please fill in all schedule details");
      return;
    }

    setSaving(true);
    try {
      // Save to backend first
      await axios.post(`http://localhost:5000/api/recruiter-actions/${applicant._id}`, {
        roundStatus,
        feedback: allFeedback,
        scheduledDate,
        scheduledTime,
        interviewerName,
        interviewerEmail,
        interviewerPhone,
        panelNumber,
        scheduledBy,
        interviewPlace,
        isRejected,
        rejectionRound: isRejected ? roundStatus : ''
      });

      // Sync to Google Sheets
      try {
        await syncToGoogleSheets(applicant._id, {
          name: applicant.name,
          email: applicant.email,
          phone: applicant.phone,
          position: applicant.jobTitle,
          status: applicant.status
        }, {
          currentRound: roundStatus,
          panel: panelNumber,
          interviewer: interviewerName,
          interviewerEmail,
          interviewerPhone,
          date: scheduledDate,
          time: scheduledTime,
          feedback: feedback
        });
        console.log('✅ Synced to Google Sheets');
      } catch (sheetErr) {
        console.error('Error syncing to Google Sheets:', sheetErr);
      }

      alert("Schedule details saved successfully!");
      setIsEditing(false);
      loadRecruiterActions();
    } catch (err) {
      console.error("Error saving schedule details:", err);
      alert("Failed to save schedule details");
    } finally {
      setSaving(false);
    }
  };

  /** Save feedback for current round */
  const handleSaveFeedback = async () => {
    if (!feedback.trim()) {
      alert("Please enter feedback before saving");
      return;
    }

    setSaving(true);
    try {
      await axios.post(`http://localhost:5000/api/recruiter-actions/${applicant._id}`, {
        roundStatus,
        feedback: feedback.trim(),
        scheduledDate,
        scheduledTime,
        interviewerName,
        interviewerEmail,
        interviewerPhone,
        panelNumber,
        scheduledBy,
        interviewPlace,
        isRejected,
        rejectionRound: isRejected ? roundStatus : ''
      });
      alert("Feedback saved successfully!");
      loadRecruiterActions();
    } catch (err) {
      console.error("Error saving feedback:", err);
      alert("Failed to save feedback");
    } finally {
      setSaving(false);
    }
  };

  /** Reject candidate */
  const handleRejectCandidate = async () => {
    if (!window.confirm(`Are you sure you want to reject ${applicant.name} in ${roundStatus}?`)) return;

    setSaving(true);
    try {
      await axios.post(`http://localhost:5000/api/recruiter-actions/${applicant._id}`, {
        roundStatus,
        feedback: feedback.trim(),
        scheduledDate,
        scheduledTime,
        interviewerName,
        interviewerEmail,
        interviewerPhone,
        panelNumber,
        scheduledBy,
        interviewPlace,
        isRejected: true,
        rejectionRound: roundStatus
      });

      await axios.post(`http://localhost:5000/api/applications/${applicant._id}/reject`);

      alert(`Candidate rejected in ${roundStatus}. Rejection email sent.`);
      setIsRejected(true);
      loadRecruiterActions();
    } catch (err) {
      console.error("Error rejecting candidate:", err);
      alert("Failed to reject candidate");
    } finally {
      setSaving(false);
    }
  };

  /** Promote candidate to next round */
  const handlePromoteToNextRound = async () => {
    const roundOrder = ["Round 1", "Round 2", "Round 3", "Final Round"];
    const currentIndex = roundOrder.indexOf(roundStatus);

    if (currentIndex === -1 || currentIndex >= roundOrder.length - 1) {
      alert("Candidate is already in the final round");
      return;
    }

    setShowPromoteModal(true);
  };

  const confirmPromoteToNextRound = async () => {
    const roundOrder = ["Round 1", "Round 2", "Round 3", "Final Round"];
    const nextRound = roundOrder[roundOrder.indexOf(roundStatus) + 1];

    setSending(true);
    try {
      await axios.post(`http://localhost:5000/api/applications/${applicant._id}/promote-round`, {
        nextRound,
        message: `Congratulations! You have cleared ${roundStatus} and are selected for ${nextRound}.`
      });
      alert(`Candidate promoted to ${nextRound} successfully! Email sent.`);
      setShowPromoteModal(false);
      loadRecruiterActions();
    } catch (err) {
      console.error("Error promoting candidate:", err);
      alert("Failed to promote candidate");
    } finally {
      setSending(false);
    }
  };

  /** Send custom email */
  const handleSendEmail = async () => {
    if (!emailData.subject || !emailData.body) {
      alert("Please fill in both subject and email body");
      return;
    }

    setSending(true);
    try {
      await axios.post("http://localhost:5000/api/send-custom-email", {
        to: applicant.email,
        subject: emailData.subject,
        body: emailData.body,
        applicantName: applicant.name
      });
      alert("Email sent successfully!");
      setShowEmailModal(false);
      setEmailData({ subject: "", body: "" });
    } catch (err) {
      console.error("Error sending email:", err);
      alert("Failed to send email");
    } finally {
      setSending(false);
    }
  };

  /** UI Loader */
  if (loading) return <div style={{ color: GAMYAM_COLORS.textLight }}>Loading...</div>;

  return (
    <div style={{ backgroundColor: GAMYAM_COLORS.darkBg, color: GAMYAM_COLORS.textLight, padding: 20 }}>
      <button onClick={onBack}><ArrowLeft /> Back</button>
      <h2>Recruiter Actions for {applicant.name}</h2>

      {/* Schedule Details Form */}
      <section>
        <h3>Schedule Details</h3>
        {isEditing ? (
          <div>
            <input type="date" value={scheduledDate} onChange={e => setScheduledDate(e.target.value)} />
            <input type="time" value={scheduledTime} onChange={e => setScheduledTime(e.target.value)} />
            <input type="text" placeholder="Interviewer Name" value={interviewerName} onChange={e => setInterviewerName(e.target.value)} />
            <input type="email" placeholder="Interviewer Email" value={interviewerEmail} onChange={e => setInterviewerEmail(e.target.value)} />
            <input type="tel" placeholder="Interviewer Phone" value={interviewerPhone} onChange={e => setInterviewerPhone(e.target.value)} />
            <input type="text" placeholder="Panel Number" value={panelNumber} onChange={e => setPanelNumber(e.target.value)} />
            <input type="text" placeholder="Scheduled By" value={scheduledBy} onChange={e => setScheduledBy(e.target.value)} />
            <input type="text" placeholder="Interview Place" value={interviewPlace} onChange={e => setInterviewPlace(e.target.value)} />
            <button onClick={handleSaveScheduleDetails} disabled={saving}><Save /> Save Schedule</button>
          </div>
        ) : (
          <div>
            <p>Date: {scheduledDate}</p>
            <p>Time: {scheduledTime}</p>
            <p>Interviewer: {interviewerName} ({interviewerEmail}, {interviewerPhone})</p>
            <p>Panel: {panelNumber}</p>
            <p>Scheduled By: {scheduledBy}</p>
            <p>Place: {interviewPlace}</p>
            <button onClick={() => setIsEditing(true)}><Edit2 /> Edit</button>
          </div>
        )}
      </section>

      {/* Feedback */}
      <section>
        <h3>Feedback</h3>
        <textarea value={feedback} onChange={e => setFeedback(e.target.value)} placeholder="Enter feedback here" rows={4}></textarea>
        <button onClick={handleSaveFeedback} disabled={saving}><Save /> Save Feedback</button>
      </section>

      {/* Actions */}
      <section>
        <h3>Actions</h3>
        <button onClick={handleRejectCandidate} disabled={saving}><XCircle /> Reject Candidate</button>
        <button onClick={handlePromoteToNextRound} disabled={sending}><CheckCircle /> Promote to Next Round</button>
        <button onClick={() => setShowEmailModal(true)} disabled={sending}><Mail /> Send Email</button>
      </section>

      {/* Email Modal */}
      {showEmailModal && (
        <div style={{ backgroundColor: GAMYAM_COLORS.darkCard, padding: 20, marginTop: 20 }}>
          <h4>Send Custom Email</h4>
          <input type="text" placeholder="Subject" value={emailData.subject} onChange={e => setEmailData({ ...emailData, subject: e.target.value })} />
          <textarea placeholder="Email Body" value={emailData.body} onChange={e => setEmailData({ ...emailData, body: e.target.value })} rows={6}></textarea>
          <button onClick={handleSendEmail} disabled={sending}><Send /> Send</button>
          <button onClick={() => setShowEmailModal(false)}><X /> Cancel</button>
        </div>
      )}

      {/* Promote Modal */}
      {showPromoteModal && (
        <div style={{ backgroundColor: GAMYAM_COLORS.darkCard, padding: 20, marginTop: 20 }}>
          <h4>Confirm Promote</h4>
          <p>Are you sure you want to promote {applicant.name} to the next round?</p>
          <button onClick={confirmPromoteToNextRound} disabled={sending}><CheckCircle /> Yes, Promote</button>
          <button onClick={() => setShowPromoteModal(false)}><X /> Cancel</button>
        </div>
      )}
    </div>
  );
}

export default RecruiterActionsPage;
